<?php
declare(strict_types=1);

require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/csrf_helper.php';
require_once __DIR__.'/includes/shop_catalog_management.php';
if(!isset($_SESSION['trener_id'])||!roleAtLeast('admin')){header('Location: login.php');exit;}
function catalogAdminH(mixed$value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function catalogAdminMoney(mixed$value):string{return$value===null?'—':number_format((int)$value/100,2,',',' ').' Kč';}

$errors=[];$actorId=(int)$_SESSION['trener_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??'')))$errors[]='Formulář vypršel. Obnovte stránku.';
    else try{
        $action=(string)($_POST['action']??'');$reason=(string)($_POST['reason']??'');$confirmed=($_POST['confirmed']??'')==='1';
        if($action==='adjust_stock'){$result=shopCatalogAdjustStock($pdo,$actorId,(int)($_POST['variant_id']??0),(string)($_POST['new_stock']??''),$reason,$confirmed);$message=$result['changed']?'Sklad byl opraven a vznikl samostatný pohyb.':'Sklad už měl zadaný stav.';}
        else{
            $ids=shopCatalogManagementIds($_POST['product_ids']??null);
            if($action==='bulk_activate'){$count=shopCatalogBulkActivate($pdo,$actorId,$ids,(array)($_POST['public_names']??[]),(array)($_POST['public_summaries']??[]),$reason,$confirmed);$message='Aktivováno produktů: '.$count.'.';}
            elseif($action==='bulk_deactivate'){$count=shopCatalogBulkDeactivate($pdo,$actorId,$ids,$reason,$confirmed);$message='Deaktivováno produktů: '.$count.'.';}
            elseif($action==='bulk_category'){$count=shopCatalogBulkAssignCategory($pdo,$actorId,$ids,(string)($_POST['target_category']??''),$reason,$confirmed);$message='Přeřazeno produktů: '.$count.'.';}
            elseif($action==='bulk_order'){$count=shopCatalogBulkSetOrder($pdo,$actorId,$ids,(array)($_POST['sort_orders']??[]),$reason,$confirmed);$message='Změněno pořadí produktů: '.$count.'.';}
            else throw new InvalidArgumentException('Neznámá katalogová akce.');
        }
        $_SESSION['catalog_management_flash']=$message;header('Location: eshop_catalog_admin.php',true,303);exit;
    }catch(Throwable$exception){if(!($exception instanceof InvalidArgumentException||$exception instanceof ShopCatalogPublicationException||$exception instanceof ShopManualCatalogException||$exception instanceof ShopCatalogManagementException))error_log('eshop_catalog_admin.php: '.$exception->getMessage());$errors[]=$exception instanceof InvalidArgumentException||$exception instanceof ShopCatalogPublicationException||$exception instanceof ShopManualCatalogException||$exception instanceof ShopCatalogManagementException?$exception->getMessage():'Operace selhala bez částečné změny.';}
}
$success=(string)($_SESSION['catalog_management_flash']??'');unset($_SESSION['catalog_management_flash']);
$allProducts=shopCatalogManagementProducts($pdo);$overview=shopCatalogManagementOverview($allProducts);$filters=['q'=>$_GET['q']??'','status'=>$_GET['status']??'','offer_type'=>$_GET['offer_type']??'','origin'=>$_GET['origin']??'','category'=>$_GET['category']??'','sort'=>$_GET['sort']??'order'];
try{$products=shopCatalogManagementFilter($allProducts,$filters);}catch(InvalidArgumentException$exception){$errors[]=$exception->getMessage();$filters=['q'=>'','status'=>'','offer_type'=>'','origin'=>'','category'=>'','sort'=>'order'];$products=shopCatalogManagementFilter($allProducts,$filters);}
$categoryNodes=shopCategoryNodes($pdo);$variants=shopCatalogManagementVariants($pdo);
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Správa katalogu</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"></head><body class="bg-light"><?php include __DIR__.'/hlavicka.php';?>
<main class="container-fluid py-4" style="max-width:1700px"><div class="d-flex justify-content-between align-items-start gap-2 mb-3"><div><h1 class="h4 mb-0"><i class="bi bi-boxes me-2 text-primary"></i>Správa katalogu</h1><div class="small text-muted">Stav, filtry, pořadí, publikace, kategorie a auditované skladové korekce.</div></div><div class="d-flex gap-2"><a class="btn btn-outline-primary btn-sm" href="eshop_produkt_admin.php">Detail produktů</a><a class="btn btn-outline-secondary btn-sm" href="eshop_admin.php">Zpět</a></div></div>
<?php foreach($errors as$error):?><div class="alert alert-danger"><?=catalogAdminH($error)?></div><?php endforeach;?><?php if($success!==''):?><div class="alert alert-success"><?=catalogAdminH($success)?></div><?php endif;?>
<div class="row g-2 mb-3"><?php foreach(['total'=>'Celkem','draft'=>'Koncept','active'=>'Aktivní','inactive'=>'Neaktivní','missing_image'=>'Bez obrázku','missing_category'=>'Bez kategorie','missing_price'=>'Bez ceny']as$key=>$label):?><div class="col-6 col-md"><div class="card border-0 shadow-sm h-100"><div class="card-body py-2"><div class="small text-muted"><?=catalogAdminH($label)?></div><div class="h4 mb-0"><?=(int)$overview[$key]?></div></div></div></div><?php endforeach;?></div>
<form method="get" class="card border-0 shadow-sm mb-3"><div class="card-body row g-2 align-items-end"><div class="col-lg-3"><label class="form-label">Hledat ve veřejném názvu a popisu</label><input class="form-control" name="q" value="<?=catalogAdminH($filters['q'])?>"></div><div class="col-lg-1"><label class="form-label">Stav</label><select class="form-select" name="status"><option value="">Vše</option><?php foreach(['draft'=>'koncept','active'=>'aktivní','inactive'=>'neaktivní']as$key=>$label):?><option value="<?=$key?>" <?=$filters['status']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Typ</label><select class="form-select" name="offer_type"><option value="">Vše</option><?php foreach(['goods','program','camp','rental','bookable_service','bookable_rental']as$key):?><option value="<?=$key?>" <?=$filters['offer_type']===$key?'selected':''?>><?=$key?></option><?php endforeach;?></select></div><div class="col-lg-1"><label class="form-label">Původ</label><select class="form-select" name="origin"><option value="">Vše</option><option value="import" <?=$filters['origin']==='import'?'selected':''?>>import</option><option value="manual" <?=$filters['origin']==='manual'?'selected':''?>>manual</option></select></div><div class="col-lg-2"><label class="form-label">Kategorie</label><select class="form-select" name="category"><option value="">Vše</option><?php foreach($categoryNodes as$node):?><option value="<?=catalogAdminH($node['category_path'])?>" <?=$filters['category']===$node['category_path']?'selected':''?>><?=catalogAdminH($node['display_name'])?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Řazení</label><select class="form-select" name="sort"><option value="order" <?=$filters['sort']==='order'?'selected':''?>>vlastní pořadí</option><option value="name" <?=$filters['sort']==='name'?'selected':''?>>název</option><option value="price" <?=$filters['sort']==='price'?'selected':''?>>cena</option></select></div><div class="col-lg-1 d-grid"><button class="btn btn-primary">Použít</button></div></div></form>
<div class="card border-warning shadow-sm mb-3"><div class="card-header bg-white fw-semibold">Auditovaná korekce skladu</div><div class="card-body"><form method="post" class="row g-2 align-items-end"><?=csrf_field()?><input type="hidden" name="action" value="adjust_stock"><div class="col-lg-5"><label class="form-label">Varianta</label><select class="form-select" name="variant_id" required><option value="">Vyberte variantu</option><?php foreach($variants as$variant):?><option value="<?=(int)$variant['id']?>"><?=catalogAdminH($variant['product_name'].' · '.$variant['sku'].' · sklad '.($variant['stock_quantity_decimal']??'neřízený'))?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Nový stav</label><input class="form-control" name="new_stock" inputmode="decimal" required></div><div class="col-lg-3"><label class="form-label">Důvod inventury / opravy</label><input class="form-control" name="reason" maxlength="1000" required></div><div class="col-lg-2"><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="confirmed" value="1" required> Potvrzuji</label><button class="btn btn-warning w-100">Zapsat pohyb</button></div></form></div></div>
<form method="post"><?=csrf_field()?><div class="card border-0 shadow-sm"><div class="card-header bg-white d-flex justify-content-between"><strong>Zobrazené produkty (<?=count($products)?>)</strong><button type="button" class="btn btn-sm btn-outline-secondary" id="select-all">Vybrat vše</button></div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th></th><th>Produkt</th><th>Stav</th><th>Kategorie / úplnost</th><th>Cena</th><th>Pořadí</th><th style="min-width:360px">Veřejný text pro aktivaci</th></tr></thead><tbody><?php foreach($products as$product):$readiness=shopCatalogPublicationReadiness($pdo,(int)$product['id']);?><tr><td><input class="form-check-input product-check" type="checkbox" name="product_ids[]" value="<?=(int)$product['id']?>"></td><td><a href="eshop_produkt_admin.php?id=<?=(int)$product['id']?>"><strong><?=catalogAdminH($product['public_name']?:$product['name'])?></strong></a><div class="small text-muted"><?=catalogAdminH($product['origin'].' · '.$product['offer_type'].' · #'.$product['id'])?></div></td><td><span class="badge <?=$product['catalog_status']==='active'?'text-bg-success':($product['catalog_status']==='inactive'?'text-bg-secondary':'text-bg-warning')?>"><?=catalogAdminH($product['catalog_status'])?></span><?php if($product['program_saleable']===false):?><div class="small text-danger mt-1"><strong>Neprodejné:</strong> <?=catalogAdminH($product['program_sale_reason'])?></div><?php endif;?><?php if(!$readiness['ready']&&$product['catalog_status']!=='active'):?><div class="small text-danger mt-1"><?=catalogAdminH(implode(' ',$readiness['blockers']))?></div><?php endif;?></td><td><div class="small"><?=catalogAdminH(implode(', ',$product['categories'])?:'bez kategorie')?></div><div class="small <?=((int)$product['image_count']&& (int)$product['category_count']&&(int)$product['priced_variant_count'])?'text-success':'text-danger'?>">obrázek <?=(int)$product['image_count']?> · kategorie <?=(int)$product['category_count']?> · cena <?=(int)$product['priced_variant_count']?></div></td><td><?=catalogAdminMoney($product['min_amount_minor'])?></td><td><input class="form-control form-control-sm" type="number" min="-100000" max="100000" name="sort_orders[<?=(int)$product['id']?>]" value="<?=(int)$product['sort_order']?>"></td><td><input class="form-control form-control-sm mb-1" name="public_names[<?=(int)$product['id']?>]" maxlength="255" value="<?=catalogAdminH($product['public_name']?:$product['name'])?>" placeholder="Veřejný název"><textarea class="form-control form-control-sm" name="public_summaries[<?=(int)$product['id']?>]" maxlength="1000" rows="2" placeholder="Veřejný popis"><?=catalogAdminH($product['public_summary']??'')?></textarea></td></tr><?php endforeach;?><?php if($products===[]):?><tr><td colspan="7" class="text-center text-muted py-4">Filtru neodpovídá žádný produkt.</td></tr><?php endif;?></tbody></table></div><div class="card-footer bg-white"><div class="row g-2 align-items-end"><div class="col-lg-3"><label class="form-label">Cílová kategorie pro přeřazení</label><select class="form-select" name="target_category"><option value="">Vyberte</option><?php foreach($categoryNodes as$node):?><option value="<?=catalogAdminH($node['category_path'])?>"><?=catalogAdminH($node['display_name'])?></option><?php endforeach;?></select></div><div class="col-lg-4"><label class="form-label">Společný auditní důvod</label><input class="form-control" name="reason" maxlength="1000" required></div><div class="col-lg-2"><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="confirmed" value="1" required> Potvrzuji vybrané produkty</label></div><div class="col-lg-3 d-flex flex-wrap gap-1"><button class="btn btn-success btn-sm" name="action" value="bulk_activate">Aktivovat</button><button class="btn btn-outline-danger btn-sm" name="action" value="bulk_deactivate">Deaktivovat</button><button class="btn btn-outline-primary btn-sm" name="action" value="bulk_category">Přeřadit</button><button class="btn btn-outline-secondary btn-sm" name="action" value="bulk_order">Uložit pořadí</button></div><div class="col-12 small text-muted">Aktivace je jedna transakce a u každého produktu znovu spouští stejnou readiness kontrolu. Přeřazení nahradí dosavadní kategorie jedinou vybranou kategorií.</div></div></div></div></form></main><script>document.getElementById('select-all')?.addEventListener('click',()=>document.querySelectorAll('.product-check').forEach(box=>box.checked=true));</script></body></html>
